import React from "react";
import axios from "axios";
import { useEffect, useState } from "react";
import { useHistory } from "react-router-dom";

const Home = () => {
  const [listOfPosts, setListOfPosts] = useState([]);
  const [loading, setLoading] = useState(true); // تم إضافة حالة التحميل
  const [error, setError] = useState(""); // تم إضافة حالة الخطأ
  let history = useHistory();

  useEffect(() => {
    axios
      .get("http://localhost:3003/posts")
      .then((response) => {
        setListOfPosts(response.data);
        setLoading(false);
      })
      .catch((error) => {
        console.error("Error fetching posts:", error);
        setError("Failed to load posts. Please make sure the server is running.");
        setLoading(false);
      });
  }, []);

  // تم إضافة معالجة حالة التحميل
  if (loading) {
    return <div>Loading posts...</div>;
  }

  // تم إضافة معالجة حالة الخطأ
  if (error) {
    return <div style={{ color: "red" }}>{error}</div>;
  }

  return (
    <div>
      {listOfPosts.length === 0 ? ( // تم إضافة رسالة إذا كانت القائمة فارغة
        <div>No posts available. Create your first post!</div>
      ) : (
        listOfPosts.map((value, key) => {
          return (
            <div
              key={key}
              className="post"
              onClick={() => {
                history.push(`/post/${value.id}`);
              }}
            >
              <div className="title">{value.title}</div>
              <div className="body">{value.postText}</div>
              <div className="footer">{value.username}</div>
            </div>
          );
        })
      )}
    </div>
  );
};

export default Home;
